      "keystrokes": "find . -name 'config.json' -o -name 'state.json' 2>/dev/null\\n",
      "duration": 0.3
    },
    {
      "keystrokes": "cat skill_context/config.json\\n",
      "duration": 0.1
    },
    {
      "keystrokes": "cat skill_context/state.json\\n",
      "duration": 0.1
    }
