      "keystrokes": "cat > skill_context/config.json << 'EOF'\n{\n  \"letter\": \"N\",\n  \"name\": \"NOVA\",\n  \"idle_timeout\": 720,\n  \"marker\": \"clawd-presence-demo\"\n}\nEOF\\n",
      "duration": 0.1
